def load_agent():
    spec = importlib.util.spec_from_file_location("autoos_agent", AGENT)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def allow_in_place(case, agent):
    """Neutralise the KEYDENY3g isolation gate for a test of something else.

    These suites drive cmd_run with a synthetic tier-2 route to reach an rc that
    has nothing to do with where the worker runs (signin probes, exit-code
    classification, free-model fallthrough, worker records). The gate refuses
    that run before it gets there. The gate is tested by
    LeafIsolationMandatoryTests / McpIsolateForceTests, which call it for real.
    """
    patch = mock.patch.object(agent, "leaf_isolation_refusal", lambda *a, **k: None)
    patch.start()
    case.addCleanup(patch.stop)


# Every cmd_run writes a worker record (ps). No test may write into the host's
# real registry (<main checkout>/logs/workers): pin it to a throwaway dir for the
# whole module; a test that needs its own dir still passes AUTOOS_WORKERS_DIR.
_WORKERS_TMP = None
_MEMINFO_TMP = None
_HOST_PINS = None


def setUpModule():
    global _WORKERS_TMP, _MEMINFO_TMP, _HOST_PINS
    _WORKERS_TMP = tempfile.mkdtemp(prefix="autoos-workers-test-")
    os.environ["AUTOOS_WORKERS_DIR"] = _WORKERS_TMP
    # HOSTADMISSION reads the host's MemAvailable, and a runner with less free
    # memory than the floor would refuse every real-launch test in this file for
    # a reason none of them is about. Pin the source to a healthy fake; the
    # admission tests name their own path per case.
    _MEMINFO_TMP = os.path.join(_WORKERS_TMP, "meminfo")
    with io.open(_MEMINFO_TMP, "w", encoding="utf-8") as fh:
        fh.write("MemTotal:       67108864 kB\nMemFree:        1 kB\n"
                 "MemAvailable:   67108864 kB\n")
    os.environ["AUTOOS_MEMINFO_PATH"] = _MEMINFO_TMP
    # AO-ADMISSION-2 (2026-10-09): the same argument binds for the two remaining
    # host reads. The run budget gate reads the day's spend report — on a host
    # that has spent its day every Google-paid start here is refused for a reason
    # no test in this file is about (4 GeminiSideModelPinTests, and the 2026-10-08
    # and -09 prepush overrides were exactly this), while CI, a machine with no
    # report at all, stays green. Name a report that says the day is inside
    # budget. And `AUTOOS_ADMISSION_OFF=1` is the spawner's own test-only escape
    # for host admission: a `mock.patch.dict(..., clear=True)` below the module
    # would otherwise put the live /proc/meminfo back (the escape does not reach
    # a client worker — tools/autoos-agent.py copies it to our own CLI by name).
    # HostAdmissionTests is the rule itself: it pops the escape and names both
    # sources per case.
    _HOST_PINS = host_state.install(None, directory=_WORKERS_TMP, gate="allow",
                                    workers=False, meminfo=None, admission_off=True)


def tearDownModule():
    # `uninstall` first: it puts back what `install` found, which includes the two
    # names this module set before it, so the pops below have to come after it or
    # it would put them back and leave the next test file pointing at this dir.
    if _HOST_PINS is not None:
        host_state.uninstall(_HOST_PINS)
    os.environ.pop("AUTOOS_WORKERS_DIR", None)
    os.environ.pop("AUTOOS_MEMINFO_PATH", None)
    shutil.rmtree(_WORKERS_TMP, ignore_errors=True)


def pinned_env(**extra):
    """The body of a `mock.patch.dict(os.environ, ..., clear=True)` for a test
    that drives the spawner: the caller's names, plus the host reads pinned to
    fixtures under this module's temp dir.

    `clear=True` is what makes a test independent of the calling shell — and it
    drops the module's pins with the rest of the environment, which puts the live
    spend report, the live worker count and the live MemAvailable back in the
    process under test. A test that replaces the whole environment has to name the
    fixtures itself; this is the one place that says what they are (AO-ADMISSION-2).
    """
    env = dict(_host_env_pins())
    env.update(extra)
    return env


_HOST_ENV = None


def _host_env_pins():
    """The host-read pins for this module's temp dir, built once and copied."""
    global _HOST_ENV
    if _HOST_ENV is None:
        _HOST_ENV = host_state.pin_values(_WORKERS_TMP, workers=False,
                                          admission_off=True)
    return _HOST_ENV


SHIPPED_REGISTRY = json.loads(
    (ROOT / "catalog" / "ai-registry.json").read_text(encoding="utf-8"))


def r_leg_is_claude(leg):
    """The shipped registry's own Claude predicate, for CLI-level assertions."""
    return bool(leg) and resolver.is_claude_leg(leg, SHIPPED_REGISTRY)


def clean_env(**extra):
    # An ambient AUTOOS_SESSION_TAG is the lane's own tag: a spawn run from a
    # lane session takes it instead of deriving one from ROOT, so every
    # session-tag test that does not name a tag passed on whatever the calling
    # shell happened to export (measured 2026-09-28 in a lane sandbox: two
    # SessionTagTests fail only there). The same reasoning as the key strip -
    # the suite must pass on a machine that is mid-handoff. A test that wants a
    # tag sets one: clean_env(AUTOOS_SESSION_TAG="lane/one").
    dropped = ("AUTOOS_OMNIROUTE_KEY", "AUTOOS_SESSION_TAG")
    env = {k: v for k, v in os.environ.items()
           if not k.startswith("AUTOOS_AGENT_") and k not in dropped}
    env.update(extra)
    return env


def claude_env(**extra):
    """`clean_env` plus the orchestrator's Claude declaration.

    CLAUDEBUDGET-b item 1/3(d): with the shipped `claude_budget` on, spawning
    `--client claude` is refused -- Claude is held for finals and for the work the
    orchestrator declares. The tests below that only want to look at the *claude
    client's own shape* (its argv, `--joinable`, `--lean`'s mcp config, the
    sandbox containment path) are not tests of the budget, so they declare the run
    the way an orchestrator would. The budget's own tests
    (ClaudeBudgetSpawnTests/ClaudeBudgetMcpSpawnTests) deliberately leave it unset:
    that refusal is what they measure.

    CLAUDEBUDGET-d item 2: the same declaration covers `--client agy`. What spends
    the allowance is the model that answers, and agy answers with
    `clients.AGY_DEFAULT_MODEL` = a Claude model when the caller names no --model,
    so naming that client was never a claim that the run is free.
    """
    return clean_env(AUTOOS_CLAUDE_CRITICAL="test: the claude client's own argv",
                     **extra)


def budget_on_root():
    """A throwaway ROOT whose catalog/ai-registry.json has the Claude budget ON.

    The shipped registry is `mode: normal` since the operator's 2026-10-01
    routing-00 decision (the weekly limit reset), so the spawn-path tests that
    prove the ON refusal must supply their own registry instead of reading the
    shipped value. Every top-level entry is symlinked so the CLI still sees the
    real `opencode.jsonc` and `tools/`; only `catalog/` is replaced with a copy
    of the shipped registry carrying `mode == 'budget'`. The CLI resolves ROOT
    from `os.path.abspath(__file__)`, which does not follow the `tools` symlink,
    so it reads the copy.
    """
    tmp = tempfile.mkdtemp(prefix="autoos-budget-on-")
    for entry in os.scandir(str(ROOT)):
        if entry.name == "catalog":
            continue
        os.symlink(entry.path, os.path.join(tmp, entry.name))
    os.makedirs(os.path.join(tmp, "catalog"))
    registry = json.loads((ROOT / "catalog" / "ai-registry.json")
                          .read_text(encoding="utf-8"))
    registry["policy"]["claude_budget"]["mode"] = "budget"
    with io.open(os.path.join(tmp, "catalog", "ai-registry.json"), "w",
                 encoding="utf-8") as fh:
        json.dump(registry, fh)
    return tmp


def run_agent(*args, env=None, root=None):
    agent = str(AGENT) if root is None else os.path.join(root, "tools", "autoos-agent.py")
    return subprocess.run([sys.executable, agent, *args], capture_output=True,
                          text=True, env=env or clean_env(), stdin=subprocess.DEVNULL)


class _FakeFn:
    """A callable standing in for a ctypes function. ctypes functions carry
    ``restype``/``argtypes``; the production helper assigns them, so the fake
    must expose writable attributes on a per-instance callable (bound methods
    do not)."""

    def __init__(self, fn):
        self._fn = fn
        self.restype = None
        self.argtypes = None

    def __call__(self, *args, **kwargs):
        return self._fn(*args, **kwargs)


class _FakeKernel32:
    """A fake ctypes kernel32 for the Windows liveness/start-time paths (V1/V2).

    Runs on Linux: the production code imports ctypes inside its
    ``os.name == "nt"`` branch, so injecting this module into ``sys.modules``
    is exactly what it sees. ``byref`` returns the ctypes-like value object
    itself, so the fake Get* calls can write ``.value`` on it.
    """

    def __init__(self, handle=1234, exit_code=259, created=987654321,
                 last_error=0, times_ok=True):
        self.handle = handle
        self.exit_code = exit_code
        self.created = created
        self.last_error = last_error
        self.times_ok = times_ok
        self.opened = []
        self.closed = []
        self.OpenProcess = _FakeFn(self._open_process)
        self.GetExitCodeProcess = _FakeFn(self._get_exit_code_process)
        self.GetProcessTimes = _FakeFn(self._get_process_times)
        self.CloseHandle = _FakeFn(self._close_handle)

    def _open_process(self, access, inherit, pid):
        self.opened.append((access, inherit, pid))
        return self.handle

    def _get_exit_code_process(self, handle, code):
        code.value = self.exit_code
        return 1

    def _get_process_times(self, handle, created, exited, kernel, user):
        if not self.times_ok:
            return 0
        created.value = self.created
        return 1

    def _close_handle(self, handle):
        self.closed.append(handle)
        return 1


class _FakeCtypesValue:
    def __init__(self, value=0):
        self.value = value


def fake_windows_ctypes(k32):
    """A ctypes stand-in whose kernel32 is `k32` (V1/V2 tests).

    ``WinDLL`` is what the production helper now asks for (typed signatures);
    ``wintypes`` carries the sentinels the tests assert the helper assigned.
    """
    fake = types.ModuleType("ctypes")
    fake.k32 = k32
    fake.windll = types.SimpleNamespace(kernel32=k32)
    fake.WinDLL = lambda *args, **kwargs: k32
    fake.wintypes = types.SimpleNamespace(HANDLE=object(), DWORD=_FakeCtypesValue,
                                          BOOL=object(), FILETIME=object())
    fake.POINTER = lambda typ: typ
    fake.get_last_error = lambda: k32.last_error
    fake.byref = lambda obj: obj
    fake.c_ulong = _FakeCtypesValue
    fake.c_ulonglong = _FakeCtypesValue
    return fake


class RoutingTableTests(unittest.TestCase):
    """ADR 0006 decision 3: one test per row of the resolution table."""

    def pick(self, **card):
        return routing.select_combo(card)[0]

    def test_empty_card_is_t2_worker(self):
        combo, reason = routing.select_combo({})
        self.assertEqual(combo, "l2-worker")
        self.assertTrue(reason)

    def test_public_1m_routes_to_t1_orchestrator(self):
        # T1FREE 2026-09-27: l1-orchestrator now carries a free gemini/gemini-3.8-flash
        # fallback leg, so ctx=1m public cards route there again.
        for card in ({"ctx": "1m", "role": "orchestrate"},
                     {"ctx": "1m", "complexity": "hard"},
                     {"ctx": "1m", "role": "review", "spend": "free-ok"}):
            combo, reason = routing.select_combo(card)
            self.assertEqual(combo, "l1-orchestrator")
            self.assertEqual(reason, "public-1m")

    def test_public_implement_standard_free_is_t2_worker(self):
        self.assertEqual(self.pick(role="implement", complexity="standard", spend="free-ok"), "l2-worker")

    def test_public_review_free_is_t3_driver(self):
        self.assertEqual(self.pick(role="review"), "l3-driver")

    def test_public_trivial_free_is_t3_driver(self):
        self.assertEqual(self.pick(complexity="trivial"), "l3-driver")

    # DEADROWS 2026-10-08 dropped the two `spend=credit` rows of this table:
    # the -credit chains went 2026-09-23, the spawner's TIERS has no credit
    # tier, so credit only ever resolved to the combo the free-ok rows above
    # already pin. The value itself is now refused — see
    # RoutingBoundaryTests.test_spend_credit_is_refused_naming_its_values.

    def test_every_combo_exists_and_none_is_retired(self):
        retired = {"tier1", "tier1-clean", "tier2", "tier2-clean", "tier3", "tier3-clean", "rag",
                   "tier1-paid", "tier2-paid", "tier3-paid", "tier2-credit", "tier3-credit"}
        with open(ROOT / "configuration" / "omniroute" / "combos.json", encoding="utf-8") as fh:
            live = {c["name"] for c in json.load(fh)["combos"]}
        self.assertFalse(retired & set(routing.ALL_COMBOS))
        self.assertLessEqual(set(routing.ALL_COMBOS), live)
        # Every card the resolver accepts, not just the hand-kept tuple.
        import itertools
        fields = list(routing.CARD_VALUES)
        for values in itertools.product(*(routing.CARD_VALUES[f] for f in fields)):
            for allow in (False, True):
                try:
                    combo = routing.select_combo(dict(zip(fields, values)), allow)[0]
                except routing.NoRoute:
                    continue
                self.assertIn(combo, routing.ALL_COMBOS, (values, allow))

    def test_sensitive_implement_is_t2_worker_clean(self):
        self.assertEqual(self.pick(privacy="sensitive"), "l2-worker-clean")

    def test_sensitive_hard_is_t2_worker_clean(self):
        self.assertEqual(self.pick(privacy="sensitive", complexity="hard", spend="free-ok"), "l2-worker-clean")

    def test_sensitive_review_is_t3_driver_clean(self):
        self.assertEqual(self.pick(privacy="sensitive", role="review"), "l3-driver-clean")

    def test_sensitive_trivial_is_t3_driver_clean(self):
        self.assertEqual(self.pick(privacy="sensitive", complexity="trivial"), "l3-driver-clean")

    def test_sensitive_1m_has_no_route_and_says_what_to_do(self):
        with self.assertRaises(routing.NoRoute) as ctx:
            routing.select_combo({"privacy": "sensitive", "ctx": "1m"})
        msg = str(ctx.exception)
        self.assertIn("l2-worker-clean", msg)
        self.assertIn("128k", msg)
        self.assertNotIn("--allow-training", msg)


class RoutingBoundaryTests(unittest.TestCase):
    """ADR 0006: unknown fields and values are errors; boundary cases are fixed."""

    def test_unknown_field_is_rejected(self):
        with self.assertRaises(routing.CardError) as ctx:
            routing.select_combo({"model": "l1-orchestrator"})
        self.assertIn("model", str(ctx.exception))

    def test_unknown_value_is_rejected(self):
        with self.assertRaises(routing.CardError):
            routing.select_combo({"privacy": "secret"})

    def test_each_field_has_its_documented_default(self):
        self.assertEqual(routing.CARD_DEFAULTS, {
            "role": "implement", "complexity": "standard", "ctx": "128k",
            "privacy": "public", "spend": "free-ok"})

    def test_role_values(self):
        self.assertEqual(routing.CARD_VALUES["role"], ("orchestrate", "implement", "review"))

    def test_complexity_values(self):
        self.assertEqual(routing.CARD_VALUES["complexity"], ("trivial", "standard", "hard"))

    def test_ctx_values(self):
        self.assertEqual(routing.CARD_VALUES["ctx"], ("128k", "1m"))

    def test_privacy_values(self):
        self.assertEqual(routing.CARD_VALUES["privacy"], ("public", "sensitive"))

    def test_spend_values(self):
        # DEADROWS 2026-10-08: `credit` left the allowed set — the -credit
        # combos went 2026-09-23, ALL_COMBOS has no credit route and the
        # spawner's TIERS has no credit tier, so the value asked for something
        # nothing could serve.
        self.assertEqual(routing.CARD_VALUES["spend"], ("free-ok",))

    def test_spend_credit_is_refused_naming_its_values(self):
        # The card is refused at parse time, not silently re-routed.
        for card in ({"spend": "credit"},
                     {"role": "implement", "spend": "credit"},
                     {"privacy": "sensitive", "spend": "credit"}):
            with self.assertRaises(routing.CardError) as ctx:
                routing.select_combo(card)
            msg = str(ctx.exception)
            self.assertIn("spend", msg)
            self.assertIn("credit", msg)
            self.assertIn("free-ok", msg)
        # The same refusal on the v1 path of normalize_v2, and on a key=value card.
        with self.assertRaises(routing.CardError):
            routing.normalize_v2(routing.parse_card("role=review,spend=credit"))

    def test_public_128k_orchestrate_goes_to_t1_orchestrator(self):
        # T1FREE 2026-09-27: l1-orchestrator serves public-strong again (ctx=128k +
        # orchestrate/hard) through its gemini fallback leg.
        self.assertEqual(routing.select_combo({"role": "orchestrate"})[0], "l1-orchestrator")
        self.assertEqual(routing.select_combo({"role": "orchestrate"})[1], "public-strong")

    def test_hard_review_is_t1_orchestrator_not_t3_driver(self):
        # orchestrate/hard wins over review/trivial: a hard review needs the strong model.
        # T1FREE 2026-09-27: l1-orchestrator serves public-strong again.
        self.assertEqual(routing.select_combo({"role": "review", "complexity": "hard"})[0], "l1-orchestrator")

    def test_sensitive_orchestrate_128k_is_t2_worker_clean(self):
        self.assertEqual(routing.select_combo({"privacy": "sensitive", "role": "orchestrate"})[0], "l2-worker-clean")

    def test_allow_training_no_longer_opens_sensitive_1m(self):
        # Compatibility flag, inert since DSMAX 2026-09-27: there is no
        # trainable 1M gateway leg left for it to unlock.
        with self.assertRaises(routing.NoRoute):
            routing.select_combo({"privacy": "sensitive", "ctx": "1m"}, allow_training=True)

    def test_allow_training_changes_nothing_else(self):
        self.assertEqual(routing.select_combo({"privacy": "sensitive"}, allow_training=True)[0], "l2-worker-clean")

    def test_parse_card_reads_key_value_pairs(self):
        self.assertEqual(routing.parse_card("role=review, privacy=sensitive"),
                         {"role": "review", "privacy": "sensitive"})

    def test_parse_card_reads_json(self):
        self.assertEqual(routing.parse_card('{"ctx": "1m"}'), {"ctx": "1m"})

    def test_parse_card_rejects_a_bare_word(self):
        with self.assertRaises(routing.CardError):
            routing.parse_card("review")

    def test_every_combo_the_resolver_can_return_is_declared(self):
        agent = load_agent()
        declared = agent.declared_models(agent.load_jsonc(str(ROOT / "opencode.jsonc")))
        for combo in routing.ALL_COMBOS:
            self.assertIn("omniroute/" + combo, declared)

    def test_routing_version_is_set(self):
        self.assertRegex(routing.ROUTING_VERSION, r"^\d+(\.\d+)*$")


class ClientMatrixTests(unittest.TestCase):
    def test_every_client_declares_the_matrix_fields(self):
        names = set(clients.CLIENTS)
        self.assertEqual(names, {"opencode", "claude", "qwen", "gemini", "codex", "agy", "qoder"})
        for c in clients.CLIENTS.values():
            self.assertIsInstance(c.headless, bool, c.name)
            self.assertIsInstance(c.gateway, bool, c.name)
            self.assertIsInstance(c.subagents, bool, c.name)
            self.assertTrue(c.auth, c.name)
            self.assertTrue(c.binary, c.name)

    def test_gateway_clients_are_exactly_the_omniroute_run_targets(self):
        gw = {n for n, c in clients.CLIENTS.items() if c.gateway}
        self.assertEqual(gw, {"opencode", "qwen", "gemini", "codex"})

    def test_auth_names_env_vars_or_logins_never_values(self):
        for c in clients.CLIENTS.values():
            self.assertNotRegex(c.auth, r"sk-|[A-Za-z0-9]{32,}", c.name)

    def test_only_qoder_is_a_promo(self):
        self.assertEqual({n for n, c in clients.CLIENTS.items() if c.promo}, {"qoder"})

    def test_list_prints_the_matrix_and_says_agy_and_qoder_skip_the_gateway(self):
        # An empty PATH: `list` probes agy's sign-in, and a test never runs
        # the host's real agy (review 2026-09-25).
        empty = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, empty, True)
        out = run_agent("list", env=clean_env(PATH=empty)).stdout
        for name in clients.CLIENTS:
            self.assertIn(name, out)
        for line in out.splitlines():
            if line.startswith(("agy ", "qoder ")):
                self.assertIn("own auth", line)


def plan_of(*args, env=None):
    r = run_agent("run", "--dry-run", *args, env=env)
    return r


class ClientCommandTests(unittest.TestCase):
    def test_qwen_goes_through_omniroute_run_with_the_card_combo(self):
        r = plan_of("--client", "qwen", "--card", "role=review", "t")
        self.assertEqual(r.returncode, 0, r.stderr)
        self.assertIn("would run: omniroute run qwen --model l3-driver --api-key-env AUTOOS_OMNIROUTE_KEY -- ", r.stdout)
        self.assertIn("--approval-mode plan", r.stdout)

    def test_gemini_goes_through_omniroute_run(self):
        r = plan_of("--client", "gemini", "t")
        self.assertIn("omniroute run gemini --model l2-worker ", r.stdout)
        self.assertIn("--approval-mode auto_edit -p t", r.stdout)

    def test_gemini_trusts_the_spawn_cwd_for_this_session_only(self):
        # Live 2026-09-25: headless gemini in an untrusted folder exits 55
        # ("not running in a trusted directory") and downgrades the approval
        # mode. --skip-trust trusts it for this one session, nothing persists.
        r = plan_of("--client", "gemini", "t")
        self.assertIn("-- --skip-trust --approval-mode auto_edit -p t", r.stdout)

    def test_codex_runs_exec_through_omniroute(self):
        r = plan_of("--client", "codex", "t")
        self.assertIn("omniroute run codex --model l2-worker --api-key-env AUTOOS_OMNIROUTE_KEY --",
                      r.stdout)
        self.assertIn("exec --sandbox workspace-write --skip-git-repo-check t", r.stdout)

    def test_codex_header_overrides_precede_the_exec_subcommand(self):
        # FLEETP0 review item 4, measured 2026-09-28 against a listener the
        # launcher was pointed at: -c before `exec` merges into the provider the
        # launcher configured and the header rides the request; the same -c after
        # `exec` replaces model_providers wholesale and codex refuses to start.
        headers = {"x-omniroute-session-id": "lane/t/20260928-092516-fix-the-router-abc123",
                   "X-AutoOS-Run-Id": "20260928-092516-fix-the-router-abc123"}
        cmd = clients.build_command(clients.CLIENTS["codex"], "task", "combo",
                                    "edit", "m", None, headers)
        sep = cmd.index("--")
        self.assertEqual(cmd[:sep], ["omniroute", "run", "codex", "--model", "m",
                                     "--api-key-env", "AUTOOS_OMNIROUTE_KEY"])
        self.assertEqual(cmd[sep + 1:sep + 5],
                         ["-c", 'model_providers.omniroute.http_headers.'
                                'x-omniroute-session-id="lane/t/20260928-092516-fix-the-router-abc123"',
                          "-c", 'model_providers.omniroute.http_headers.'
                                'X-AutoOS-Run-Id="20260928-092516-fix-the-router-abc123"'])
        self.assertEqual(cmd[sep + 5], "exec")
        self.assertEqual(cmd[-1], "task", "the brief still lands in the last argv")

    def test_a_client_with_no_argv_header_hook_ignores_the_headers(self):
        # gemini carries by env (autoos-agent.py sets it), qwen carries nothing:
        # neither gets an -c it cannot use.
        for name in ("qwen", "gemini"):
            cmd = clients.build_command(clients.CLIENTS[name], "task", "combo",
                                        "edit", "m", None, {"x-a": "b"})
            self.assertNotIn("-c", cmd, name)
            self.assertEqual(cmd[-1], "task", name)

    def test_claude_is_headless_print_on_its_own_login(self):
        r = plan_of("--client", "claude", "t", env=claude_env())
        # FAMILYFENCE-b: the run is handed the session id whose transcript the
        # spawner will read afterwards, so the line is no longer a fixed string.
        self.assertRegex(r.stdout, r"would run: claude -p --permission-mode acceptEdits "
                         r"--session-id [0-9a-f]{8}-[0-9a-f-]+ t")
        self.assertNotIn("AUTOOS_OMNIROUTE_KEY", r.stdout)

    def test_claude_joinable_is_a_background_remote_control_session(self):
        r = plan_of("--client", "claude", "--joinable", "--title", "d1", "t",
                    env=claude_env())
        self.assertIn("claude --bg --remote-control d1 --strict-mcp-config --mcp-config "
                      "'{\"mcpServers\":{}}' --name d1", r.stdout)

    def test_a_joinable_session_starts_no_user_scope_mcp_server(self):
        # Measured 2026-09-25: user-scope graphify (docker run -i --rm -v $PWD)
        # started one container per lane worktree. --mcp-config is variadic:
        # a non-variadic option must follow it, or it eats the prompt.
        cmd = clients.build_command(clients.CLIENTS["claude"], "task", None, "edit", None, "d1")
        self.assertIn("--strict-mcp-config", cmd)
        i = cmd.index("--mcp-config")
        self.assertEqual(json.loads(cmd[i + 1]), {"mcpServers": {}})
        self.assertTrue(cmd[i + 2].startswith("--"), cmd)
        self.assertEqual(cmd[-1], "task")

    def test_joinable_is_refused_for_other_clients(self):
        self.assertEqual(plan_of("--client", "qwen", "--joinable", "t").returncode, 2)

    def test_agy_uses_its_own_login(self):
        # AGYFIX item 1 (measured 2026-09-27, K3 audit): agy 1.2.12 reads
        # "--model" as the -p prompt when -p comes first, so the model must
        # go BEFORE -p. Item 2: with no caller model it gets the measured
        # working default (claude-opus-4-6-thinking, PONG in 8 s), not its
        # own default Gemini whose quota is out until ~2026-10-01.
        r = plan_of("--client", "agy", "t", env=claude_env())
        # CLAUDE55 2026-10-05 (operator): the 4-6 generation is retired upstream;
        # the default is the balanced 5-5 rung (see AGY_DEFAULT_MODEL).
        self.assertIn("would run: agy --model claude-opus-5-5-medium -p t", r.stdout)
        self.assertNotIn("omniroute run", r.stdout)

    def test_agy_puts_an_explicit_model_before_the_print_prompt(self):
        # AGYFIX item 1: working form measured in the K3 audit is
        # `agy --model <m> -p <task>`; `agy -p --model <m> <task>` makes agy
        # take "--model" as the prompt and ignore the task.
        cmd = clients.build_command(clients.CLIENTS["agy"], "task", None, "edit",
                                    "claude-sonnet-4-6")
